def max_rob_circular(nums):
    n = len(nums)
    if n == 0:
        return 0
    if n == 1:
        return nums[0]

    def rob_range(arr, start, end): # end is exclusive
        if start >= end:
            return 0
        if start + 1 == end:
            return arr[start]

        prev2 = 0
        prev1 = arr[start]

        for i in range(start + 1, end):
            current = max(arr[i] + prev2, prev1)
            prev2 = prev1
            prev1 = current
        return prev1

    # Case 1: Exclude the last house (nums[n-1]), rob houses from index 0 to n-2
    result1 = rob_range(nums, 0, n - 1)

    # Case 2: Exclude the first house (nums[0]), rob houses from index 1 to n-1
    result2 = rob_range(nums, 1, n)

    return max(result1, result2)

